import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    out_lines = []
    while True:
        try:
            N = int(next(it))
            K = int(next(it))
        except StopIteration:
            break
        arr = [int(next(it)) for _ in range(N)]
        counts = [0] * (K + 1)
        for x in arr:
            counts[x] += 1
        out = []
        for i in range(K + 1):
            if counts[i]:
                out.extend([str(i)] * counts[i])
        out_lines.append(' '.join(out))
    print('\n'.join(out_lines))

if __name__ == "__main__":
    main()
